# -*- coding: utf-8 -*-
"""조사표.md = prices.json(가락시장 경락가 2026·2025, 상품 평균·등급) + 계산(반올림 전) + 조사_김장.md"""
import json, os, runpy
H = os.path.dirname(os.path.abspath(__file__)); G = runpy.run_path(f"{H}/build_data.py", run_name="short"); P = G["P"]
L = ["# 조사표 — 김장 비용 2026", "", "## 가락시장 경락가 (KAMIS 도매가격(가락시장 경락가격), 11/12~11/25 일별 평균가의 평균)"]
for k in sorted(P): o = P[k]; L.append(f"- {k}: 평균 {o['avg']:,}원 · {o['days']}일 · {o['lo']:,}~{o['hi']:,} · 마지막 {o['last_date']} {o['last']:,}")
L += ["", "## 계산 (반올림 전)", f"- 배추 한 포기(10kg망 ÷ 3): 상 2026 {G['B26']:,.0f} · 2025 {G['B25']:,.0f} · 중 2026 {G['BM26']:,.0f} · 하 2026 {G['A'](2026, '배추', '10키로망대', '하') / 3:,.0f} (100원 단위 반올림 2,200·4,000·1,800·1,400)"]
L.append("- 전년 대비 %: " + ", ".join(f"{n} {(b - a) / a * 100:.1f} (반올림 {G['PC'][n]})" for n, a, b, _ in G["CH"]))
L.append("- aT 20포기 → 10포기(절반): " + ", ".join(f"{k} {v:,.0f}" for k, v in G["H10"].items()) + f" · 8개 합 {sum(G['H10'].values()):,.0f} · 나머지 {G['REST']:,.0f} · 양파+나머지 {G['REST'] + G['H10']['양파']:,.0f} · 무+쪽파+대파 {G['H10']['무'] + G['H10']['쪽파'] + G['H10']['대파']:,.0f}")
L.append(f"- aT 합계 절반: 11/9 {G['AT20_9'] / 2:,.0f} · 11/16 {G['AT20'] / 2:,.0f} · 작년 11월 중순 {G['AT_LY'] / 2:,.0f} · 차이 {G['AT_LY'] / 2 - G['AT20'] / 2:,.0f}")
L.append("- 가락 도매로 10포기 분량: " + ", ".join(f"{k} {v:,.0f}" for k, v in G["W10"].items()))
L.append(f"- 절임배추 20kg 상 {G['JL']:,} → 10포기(7~9포기/박스): {G['J_LO']:,.0f}~{G['J_HI']:,.0f} · 신선배추 도매 10포기 {G['W10']['배추']:,.0f} · 차이 {G['J_LO'] - G['W10']['배추']:,.0f}~{G['J_HI'] - G['W10']['배추']:,.0f}")
L.append(f"- 배추 최근 2주 가장 높은 날 {G['DHI'][0]} {G['DHI'][1]:,} · 가장 낮은 날 {G['DLO'][0]} {G['DLO'][1]:,}")
L += ["- 기타 수치: 10포기 20포기 3포기 1kg 10kg 20kg 2.5개 5개 0.45kg 0.65kg 0.4kg 0.9kg 1.3kg 0.8kg 2kg · 7~9포기 13포기 · 4명 · 2주 · 11월 12일 25일 1~10일 17일 9일 16일 · 12월 · 1만~2만 원 · 40.2% 21.6% 49.5% 9.6% 9.0% 14.8% 42% 46.6% 42.8% 24.5% 21% 23.4포기 41.4% 60% 18.5% 11.1% 121만 4천 · 1,900원 2,469원 6,510원 199,456원 288,500원 360,340원 54,980원 80,000원 187,613원 19만 9,456원 28만 8,500원 36만 340원 5만 4,980원 8만 원 1,000가구 · 3가지 5가지 8가지 · 8천 원 · 5,000원 7,000원", "", "---", open(f"{H}/조사_김장.md", encoding="utf-8").read()]
open(f"{H}/조사표.md", "w", encoding="utf-8").write("\n".join(L)); print("ok")
